class Solution {
    private static class Fenwick{
        int[] tree;
        Fenwick(int n){
            tree=new int[n+1];
        }
        void add(int index){
            for(;index<tree.length;index+=index&-index)tree[index]++;
        }
        int query(int index){
            int sum=0;
            for(;index>0;index-=index&-index)sum+=tree[index];
            return sum;
        }
    }
    public int createSortedArray(int[] instructions){
        final int MOD=1_000_000_007;
        Fenwick fenwick=new Fenwick(Arrays.stream(instructions).max().getAsInt());
        long cost=0;
        for(int i=0;i<instructions.length;i++){
            int value=instructions[i],less=fenwick.query(value-1),greater=i-fenwick.query(value);
            cost=(cost+Math.min(less,greater))%MOD;
            fenwick.add(value);
        }
        return (int)cost;
    }
}

code.kotlin:
class Solution {
    private class Fenwick(n:Int){
        val tree=IntArray(n+1);
        fun add(indexValue:Int){
            var index=indexValue;
            while(index<tree.size){
                tree[index]++;
                index+=index and -index
            }
        };
        fun query(indexValue:Int):Int{
            var index=indexValue;
            var sum=0;
            while(index>0){
                sum+=tree[index];
                index-=index and -index
            };
            return sum
        }
    };
    fun createSortedArray(instructions:IntArray):Int{
        val mod=1_000_000_007L;
        val fenwick=Fenwick(instructions.maxOrNull()!!);
        var cost=0L;
        for(i in instructions.indices){
            val value=instructions[i];
            val less=fenwick.query(value-1);
            val greater=i-fenwick.query(value);
            cost=(cost+minOf(less,greater))%mod;
            fenwick.add(value)
        };
        return cost.toInt()
    }
}

